S=[]
for a in range(16):
 x=[a>>i&1 for i in range(4)];q=[x[0]*x[1],x[0]*x[2],x[0]*x[3]^x[1]*x[2]]
 S.append(a+sum(v<<(4+j) for j,v in enumerate(q)))
