 S.append(a+sum(v<<(4+j) for j,v in enumerate(q)))
SS=set(S);F=collections.defaultdict(list)
def rank(bs):
 D={}
 for b in bs:
  while b:
   j=b.bit_length()-1
   if j in D:b^=D[j]
   else:D[j]=b;break
 return len(D)
